import { defineConfig } from 'tsup';

/**
 * Own-key and per-target runner builds (core DESIGN R27, R30): `scripts/package-runner.sh --pubkey <file.pub>` sets
 * AOM_RUNNER_BUILD_PUBKEY to the key line, and it is compiled in as the release key the runner trusts
 * (src/update/release-key.ts). Unset: the official key generated by scripts/set-runner-release-key.sh.
 */
const buildPubkey = (process.env.AOM_RUNNER_BUILD_PUBKEY ?? '').trim();
if (buildPubkey && !/^RW[A-Za-z0-9+/]{54}$/.test(buildPubkey))
  throw new Error('AOM_RUNNER_BUILD_PUBKEY is not a minisign public key line (RW... of 56 characters)');

const shared = {
  format: ['esm'] as const,
  outDir: 'dist',
  target: 'node22' as const,
  platform: 'node' as const,
  outExtension: () => ({ js: '.mjs' }),
  define: { __AOM_RUNNER_RELEASE_PUBKEY__: JSON.stringify(buildPubkey) },
  // `yaml` (a dependency of @aom/shared, bundled in) is CommonJS and calls `require`: give the ESM bundle one.
  banner: {
    js: "import { createRequire as __aomCreateRequire } from 'node:module'; const require = __aomCreateRequire(import.meta.url);",
  },
};

export default defineConfig([
  {
    ...shared,
    entry: { 'aom-runner': 'src/cli.ts', 'mock-agent': 'src/adapters/mock-agent.ts' },
    clean: true,
    noExternal: ['@aom/shared'],
    // The project graph indexer's tree-sitter runtime and grammars (WASM) ship next to the bundle, with their licences;
    // so does the approvals page (dist/window: its static files, the web app's tokens and logos, the Geist font).
    onSuccess: 'node scripts/copy-grammars.mjs && node scripts/copy-window-assets.mjs',
    // Several deps (commander, ws, execa) are CJS/ESM mixes: keep them external, they are runtime dependencies.
  },
  {
    ...shared,
    // `aom` is what agents run. A call with a pipe, redirect, `;` or `cd` stays inside Claude Code's shell sandbox,
    // where node_modules under /home is unreadable: bundle every dependency so the file stands alone.
    entry: { aom: 'src/aom/aom-cli.ts' },
    clean: false,
    noExternal: [/.*/],
  },
]);
